SELECT `cc_name`, `d_year`, `d_moy`,
CAST(`avg_monthly_sales` AS DECIMAL(22, 6)) AS `avg_monthly_sales`,
`sum_sales`, `psum`, `nsum`
FROM (SELECT `cc_name`, `d_year`, `d_moy`, `avg_monthly_sales`, `sum_sales`, `psum`, `nsum`, `sum_sales` - `avg_monthly_sales` AS `__calcite_helper_delta`
FROM (SELECT `t3`.`cc_name`, `t3`.`d_year`, `t3`.`d_moy`, `t3`.`avg_monthly_sales`, `t3`.`sum_sales`, `t8`.`sum_sales` AS `psum`, `t13`.`sum_sales` AS `nsum`
FROM (SELECT `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name`, `date_dim`.`d_year`, `date_dim`.`d_moy`, CASE WHEN COUNT(`catalog_sales`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales`.`cs_sales_price`), 0) END AS `sum_sales`, CAST(CASE WHEN (COUNT(CASE WHEN COUNT(`catalog_sales`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name`, `date_dim`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) > 0 THEN CAST(SUM(CASE WHEN COUNT(`catalog_sales`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name`, `date_dim`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS DECIMAL(19, 0)) ELSE NULL END / (COUNT(CASE WHEN COUNT(`catalog_sales`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name`, `date_dim`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) AS DECIMAL(19, 0)) AS `avg_monthly_sales`, RANK() OVER (PARTITION BY `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name` ORDER BY `date_dim`.`d_year` IS NULL, `date_dim`.`d_year`, `date_dim`.`d_moy` IS NULL, `date_dim`.`d_moy`) AS `rn`
FROM `item`,
`catalog_sales`,
`date_dim`,
`call_center`
WHERE `catalog_sales`.`cs_item_sk` = `item`.`i_item_sk` AND `catalog_sales`.`cs_sold_date_sk` = `date_dim`.`d_date_sk` AND `call_center`.`cc_call_center_sk` = `catalog_sales`.`cs_call_center_sk` AND (`date_dim`.`d_year` = 2000 OR `date_dim`.`d_year` = 2000 - 1 AND `date_dim`.`d_moy` = 12 OR `date_dim`.`d_year` = 2000 + 1 AND `date_dim`.`d_moy` = 1)
GROUP BY `item`.`i_category`, `item`.`i_brand`, `call_center`.`cc_name`, `date_dim`.`d_year`, `date_dim`.`d_moy`) AS `t3`,
(SELECT `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name`, `date_dim0`.`d_year`, `date_dim0`.`d_moy`, CASE WHEN COUNT(`catalog_sales0`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales0`.`cs_sales_price`), 0) END AS `sum_sales`, CAST(CASE WHEN (COUNT(CASE WHEN COUNT(`catalog_sales0`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales0`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name`, `date_dim0`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) > 0 THEN CAST(SUM(CASE WHEN COUNT(`catalog_sales0`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales0`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name`, `date_dim0`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS DECIMAL(19, 0)) ELSE NULL END / (COUNT(CASE WHEN COUNT(`catalog_sales0`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales0`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name`, `date_dim0`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) AS DECIMAL(19, 0)) AS `avg_monthly_sales`, RANK() OVER (PARTITION BY `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name` ORDER BY `date_dim0`.`d_year` IS NULL, `date_dim0`.`d_year`, `date_dim0`.`d_moy` IS NULL, `date_dim0`.`d_moy`) AS `rn`
FROM `item` AS `item0`,
`catalog_sales` AS `catalog_sales0`,
`date_dim` AS `date_dim0`,
`call_center` AS `call_center0`
WHERE `catalog_sales0`.`cs_item_sk` = `item0`.`i_item_sk` AND `catalog_sales0`.`cs_sold_date_sk` = `date_dim0`.`d_date_sk` AND `call_center0`.`cc_call_center_sk` = `catalog_sales0`.`cs_call_center_sk` AND (`date_dim0`.`d_year` = 2000 OR `date_dim0`.`d_year` = 2000 - 1 AND `date_dim0`.`d_moy` = 12 OR `date_dim0`.`d_year` = 2000 + 1 AND `date_dim0`.`d_moy` = 1)
GROUP BY `item0`.`i_category`, `item0`.`i_brand`, `call_center0`.`cc_name`, `date_dim0`.`d_year`, `date_dim0`.`d_moy`) AS `t8`,
(SELECT `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name`, `date_dim1`.`d_year`, `date_dim1`.`d_moy`, CASE WHEN COUNT(`catalog_sales1`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales1`.`cs_sales_price`), 0) END AS `sum_sales`, CAST(CASE WHEN (COUNT(CASE WHEN COUNT(`catalog_sales1`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales1`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name`, `date_dim1`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) > 0 THEN CAST(SUM(CASE WHEN COUNT(`catalog_sales1`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales1`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name`, `date_dim1`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS DECIMAL(19, 0)) ELSE NULL END / (COUNT(CASE WHEN COUNT(`catalog_sales1`.`cs_sales_price`) = 0 THEN NULL ELSE COALESCE(SUM(`catalog_sales1`.`cs_sales_price`), 0) END) OVER (PARTITION BY `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name`, `date_dim1`.`d_year` RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING)) AS DECIMAL(19, 0)) AS `avg_monthly_sales`, RANK() OVER (PARTITION BY `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name` ORDER BY `date_dim1`.`d_year` IS NULL, `date_dim1`.`d_year`, `date_dim1`.`d_moy` IS NULL, `date_dim1`.`d_moy`) AS `rn`
FROM `item` AS `item1`,
`catalog_sales` AS `catalog_sales1`,
`date_dim` AS `date_dim1`,
`call_center` AS `call_center1`
WHERE `catalog_sales1`.`cs_item_sk` = `item1`.`i_item_sk` AND `catalog_sales1`.`cs_sold_date_sk` = `date_dim1`.`d_date_sk` AND `call_center1`.`cc_call_center_sk` = `catalog_sales1`.`cs_call_center_sk` AND (`date_dim1`.`d_year` = 2000 OR `date_dim1`.`d_year` = 2000 - 1 AND `date_dim1`.`d_moy` = 12 OR `date_dim1`.`d_year` = 2000 + 1 AND `date_dim1`.`d_moy` = 1)
GROUP BY `item1`.`i_category`, `item1`.`i_brand`, `call_center1`.`cc_name`, `date_dim1`.`d_year`, `date_dim1`.`d_moy`) AS `t13`
WHERE `t3`.`i_category` = `t8`.`i_category` AND `t3`.`i_category` = `t13`.`i_category` AND (`t3`.`i_brand` = `t8`.`i_brand` AND `t3`.`i_brand` = `t13`.`i_brand`) AND (`t3`.`cc_name` = `t8`.`cc_name` AND `t3`.`cc_name` = `t13`.`cc_name` AND (`t3`.`rn` = `t8`.`rn` + 1 AND `t3`.`rn` = `t13`.`rn` - 1))) AS `t15`
WHERE `t15`.`d_year` = 2000 AND `t15`.`avg_monthly_sales` > 0 AND CASE WHEN `t15`.`avg_monthly_sales` > 0 THEN ABS(`t15`.`sum_sales` - `t15`.`avg_monthly_sales`) / `t15`.`avg_monthly_sales` ELSE NULL END > 0.100000
ORDER BY `sum_sales` - `avg_monthly_sales` IS NULL, 8, `nsum` IS NULL, `nsum`
LIMIT 100) AS `__calcite_perf0035_mysql`
ORDER BY `__calcite_helper_delta`, `nsum`
LIMIT 100;
